  "name": "ble_llcp_process_pdu",
  "confidence": "medium",
  "docstring": "Processes a Bluetooth LE link-layer control PDU by preparing its header, creating a three-byte BLE kernel message containing the PDU byte, header result, and a constant control field, then dispatching it through the RX/indication handler.",
  "subsystem": "ble",
  "var_renames": {
    "a2": "llcp_pdu",
    "a4": "pdu_param",
    "v7": "tx_header_value",
    "v9": "tx_header_value",
    "v10": "llcp_msg"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "first byte of the input LLCP PDU copied into the message"
    },
    {
      "offset": 1,
      "meaning": "value returned by tx_header_prepare copied into the message"
    },
    {
      "offset": 2,
      "meaning": "constant 4 written as a message subtype or control field"
    }
  ]
}
